namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string CategorySlug { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeStore
{
    private static readonly List<Recipe> Recipes =
    [
        new()
        {
            Id = 1, Title = "Bruschetta", Category = "Appetizers", CategorySlug = "appetizers",
            Ingredients = ["Baguette", "Tomatoes", "Basil", "Garlic", "Olive oil"],
            Steps = ["Toast baguette slices.", "Dice tomatoes and mix with basil and garlic.", "Top bread with tomato mixture and drizzle with olive oil."],
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = ["Spaghetti", "Eggs", "Pancetta", "Parmesan", "Black pepper"],
            Steps = ["Cook spaghetti al dente.", "Fry pancetta until crisp.", "Mix eggs with parmesan.", "Toss hot pasta with pancetta, then stir in egg mixture off heat."],
            AverageRating = 4.8, RatingCount = 25
        },
        new()
        {
            Id = 3, Title = "Chocolate Lava Cake", Category = "Desserts", CategorySlug = "desserts",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour"],
            Steps = ["Melt chocolate and butter.", "Whisk eggs and sugar until fluffy.", "Fold in chocolate mixture and flour.", "Bake at 220°C for 12 minutes."],
            AverageRating = 4.9, RatingCount = 30
        },
        new()
        {
            Id = 4, Title = "Mango Smoothie", Category = "Beverages", CategorySlug = "beverages",
            Ingredients = ["Mango", "Yogurt", "Honey", "Ice"],
            Steps = ["Peel and dice mango.", "Blend all ingredients until smooth.", "Serve immediately."],
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 5, Title = "Sourdough Bread", Category = "Baking", CategorySlug = "baking",
            Ingredients = ["Bread flour", "Water", "Sourdough starter", "Salt"],
            Steps = ["Mix flour, water, and starter. Rest 30 min.", "Add salt and fold dough every 30 min for 2 hours.", "Shape and proof overnight in fridge.", "Bake in Dutch oven at 250°C for 40 minutes."],
            AverageRating = 4.7, RatingCount = 18
        },
        new()
        {
            Id = 6, Title = "Vegetable Stir Fry", Category = "Vegetarian", CategorySlug = "vegetarian",
            Ingredients = ["Bell peppers", "Broccoli", "Soy sauce", "Ginger", "Tofu", "Sesame oil"],
            Steps = ["Press and cube tofu.", "Stir-fry tofu until golden.", "Add vegetables and stir-fry 3 minutes.", "Add soy sauce and ginger, toss to coat."],
            AverageRating = 4.3, RatingCount = 14
        }
    ];

    public static IReadOnlyList<Recipe> GetAll() => Recipes;

    public static IReadOnlyList<Recipe> GetByCategory(string categorySlug) =>
        Recipes.Where(r => r.CategorySlug == categorySlug).ToList();

    public static Recipe? GetById(int id) => Recipes.FirstOrDefault(r => r.Id == id);

    public static void Add(Recipe recipe)
    {
        recipe.Id = Recipes.Count > 0 ? Recipes.Max(r => r.Id) + 1 : 1;
        Recipes.Add(recipe);
    }

    public static void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }
}

